style.css:
/* AFTER DARK — Roblox.com */

:root {
  /* swap these colors if you want */
  --my-bg: #090909;
  --my-panel: #171717;
  --my-text: #f5f5f5;
  --my-accent: #bdbdbd;
}

/* page background */
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* starry black GIF banner */
body::before {
  content: "";
  display: block;
  width: 100%;
  height: 220px;
  background-color: #050505;
  background-image:
    radial-gradient(white 1px, transparent 1.5px),
    radial-gradient(#aaa 1px, transparent 1.5px),
    url("https://i.postimg.cc/nrY9jNwW/stand-up-and-scream.gif");
  background-size: 65px 65px, 95px 95px, auto 180px;
  background-position: 10px 15px, 40px 35px, center;
  background-repeat: repeat, repeat, no-repeat;
  border-bottom: 2px solid #292929;
  pointer-events: none;
}

/* gothic-inspired typography */
h1, h2, h3, h4 {
  font-family: Georgia, serif !important;
  font-weight: 900 !important;
  letter-spacing: 1.5px !important;
  color: #fff !important;
}

/* general text */
body, button, input {
  font-family: "Trebuchet MS", sans-serif !important;
}

/* dark panels */
section, main {
  border-radius: 12px !important;
}

/* buttons */
button {
  border-radius: 10px !important;
  font-weight: bold !important;
  transition: .2s ease !important;
}

button:hover {
  filter: brightness(1.3) !important;
}

/* links */
a {
  transition: color .2s ease !important;
}

/* images */
img {
  border-radius: 10px !important;
}
